const fs = require('fs');
const path = require('path');

const brainDir = path.join('C:', 'Users', 'Asus', '.gemini', 'antigravity', 'brain');
const dirs = fs.readdirSync(brainDir);

console.log('Brain dirs:', dirs);

let recovered = false;

dirs.forEach(d => {
  const logFile = path.join(brainDir, d, '.system_generated', 'logs', 'transcript_full.jsonl');
  if (fs.existsSync(logFile)) {
    console.log('Scanning log file:', logFile);
    const content = fs.readFileSync(logFile, 'utf8');
    const lines = content.split('\n');
    for (let i = 0; i < lines.length; i++) {
      if (lines[i].includes('QUIZ_QUESTIONS') && lines[i].includes('Scaled Dot-Product') && lines[i].includes('"q1"')) {
        console.log(`Found candidate in ${d} at line ${i}!`);
        // Let's inspect this step
        try {
          const step = JSON.parse(lines[i]);
          if (step.tool_calls) {
            step.tool_calls.forEach(tc => {
              if (tc.arguments && tc.arguments.CodeContent && tc.arguments.CodeContent.includes('const QUIZ_QUESTIONS')) {
                fs.writeFileSync('recovered_st2_quiz_questions.js', tc.arguments.CodeContent, 'utf8');
                console.log('Successfully recovered quiz_questions.js from tool_calls!');
                recovered = true;
              }
              if (tc.arguments && tc.arguments.TargetFile && tc.arguments.TargetFile.includes('quiz_questions.js') && tc.arguments.ReplacementContent) {
                console.log('Found replacement tool call for quiz_questions.js');
              }
            });
          }
        } catch (e) {
          // ignore
        }
      }
    }
  }
});
